#!/bin/bash
# Builds a temporary copy of the example app that runs the iPhone benchmark harness on launch.
# Usage: bash docs/benchmarks/harness/setup-ios.sh <fixtures-dir> [real-pages-dir] [project-dir]
#   fixtures-dir:   generated by the Mac harness (GPUScaleBench writes them on first run)
#   real-pages-dir: optional folder of .jpg comic pages for the --real mode
#   project-dir:    default /tmp/ImageIOKit-device-project
set -euo pipefail
REPO="$(cd "$(dirname "$0")/../../.." && pwd)"
HERE="$REPO/docs/benchmarks/harness"
FIXTURES="$1"; REAL="${2:-}"; OUT="${3:-/tmp/ImageIOKit-device-project}"
rm -rf "$OUT" && mkdir -p "$OUT"
rsync -a --exclude .git --exclude DerivedData --exclude .build "$REPO/" "$OUT/"
PROBE="$OUT/ImageIOKitTests/SampleImages/ProbeFixtures"
mkdir -p "$PROBE"
cp "$FIXTURES"/* "$PROBE/"
if [ -n "$REAL" ]; then mkdir -p "$PROBE/real" && cp "$REAL"/*.jpg "$PROBE/real/"; fi
cp "$HERE/ios/ViewController.swift" "$OUT/ImageIOKitExample/ViewController.swift"
python3 -I - "$OUT" <<'PY'
import sys
out = sys.argv[1]
# Bundle ProbeFixtures as a folder reference in the app target, next to the WebP fixture folder.
pb = out + '/ImageIOKit.xcodeproj/project.pbxproj'
lines = open(pb).read().split('\n')
def insert_after(substring, new_line):
    matches = [i for i, l in enumerate(lines) if substring in l]
    assert len(matches) == 1, substring
    lines.insert(matches[0] + 1, new_line)
insert_after('A20000012F27000000000002 /* WebP in Resources */ = {isa = PBXBuildFile',
    '\t\tA20000012F27000000000004 /* ProbeFixtures in Resources */ = {isa = PBXBuildFile; fileRef = A10000012F27000000000003 /* ProbeFixtures */; };')
insert_after('A10000012F27000000000002 /* WebP */ = {isa = PBXFileReference',
    '\t\tA10000012F27000000000003 /* ProbeFixtures */ = {isa = PBXFileReference; lastKnownFileType = folder; path = ProbeFixtures; sourceTree = "<group>"; };')
insert_after('\t\t\t\tA10000012F27000000000002 /* WebP */,', '\t\t\t\tA10000012F27000000000003 /* ProbeFixtures */,')
insert_after('221D5F1229EBD709006E60AB /* LaunchScreen.storyboard in Resources */,', '\t\t\t\tA20000012F27000000000004 /* ProbeFixtures in Resources */,')
open(pb, 'w').write('\n'.join(lines))
# Benchmark-only: let untagged gray JPEGs through TurboJPEG as sRGB so its RGBA pipelines can be timed.
p = out + '/ImageIOKit/Internal/JPEGRegionDecoder.swift'
s = open(p).read()
guard = '''            guard !isGrayJPEG else { throw ImageDecoderError.unsupportedOperation }\n'''
if guard in s:
    s = s.replace(guard, '            // Benchmark-only: time untagged gray through TurboJPEG as sRGB.\n')
    open(p, 'w').write(s)
# Benchmark-only: the copy-upload switch so --memory can A/B shared storage against replace(region:).
p = out + '/ImageIOKit/Decoding/ImageSource+Texture.swift'
s = open(p).read()
shared = '''        let buffer = try PixelBuffer.withMetalStorage(on: scaler.device) {
            try nativeTextureSource(covering: size, targetSize: targetSize, pixelFormat: pixelFormat)
                ?? decode(targetSize: targetSize, pixelFormat: pixelFormat)
        }'''
assert shared in s, 'shared-storage anchor'
s = s.replace(shared, '''        let buffer: PixelBuffer
        if Self.benchmarkCopyUpload {
            buffer = try nativeTextureSource(covering: size, targetSize: targetSize, pixelFormat: pixelFormat)
                ?? decode(targetSize: targetSize, pixelFormat: pixelFormat)
        } else {
            buffer = try PixelBuffer.withMetalStorage(on: scaler.device) {
                try nativeTextureSource(covering: size, targetSize: targetSize, pixelFormat: pixelFormat)
                    ?? decode(targetSize: targetSize, pixelFormat: pixelFormat)
            }
        }''')
marker = 'extension ImageSource {'
assert marker in s, 'extension anchor'
s = s.replace(marker, marker + '''

    /// Benchmark-only: forces plain allocations so makeTexture uploads by copy.
    /// Patched in by setup-ios.sh; not part of the library.
    nonisolated(unsafe) static var benchmarkCopyUpload = false''', 1)
open(p, 'w').write(s)
PY
echo "Project ready in $OUT. Build and run it with the commands in README.md."
